('blackrock-buidl',
'{
  "type":"Restricted tokenized private-fund interest providing qualified investors exposure to cash, United States Treasury bills and repurchase agreements.",
  "legal_structure":{"issuer":"BlackRock USD Institutional Digital Liquidity Fund Ltd.","domicile":"British Virgin Islands","security":"Pooled investment fund interests represented by digital asset security tokens","offering":"Rule 506(c) private placement","investment_company_act":"Section 3(c)(7) exclusion"},
  "access":{"eligible_investors":"Qualified purchasers accepted through Securitize onboarding","transferability":"Only among pre-approved or whitelisted participants","initial_minimum_usd":5000000,"redemption_minimum_usd":250000,"minimum_note":"The launch release establishes the 5 million dollar initial minimum; the current redemption minimum is an RWA.xyz product-data observation and should be checked against live offering documents."},
  "current_observation":{"observed_at":"2026-08-03T16:48:03Z","source":"rwa-buidl","product_total_asset_value_usd":2673461059.240449,"net_asset_value_usd":1,"holder_addresses":113,"observed_seven_day_apy_pct":1.4705439273203145,"management_fee_range_pct":"0.20-0.50","network_names":["Aptos","Arbitrum","Avalanche C-Chain","BNB Chain","Ethereum","Optimism","Polygon","Solana","Tempo"],"native_token_rows":10,"bridge_token_rows":0},
  "economics":{"portfolio":"Cash, United States Treasury bills and repurchase agreements","income_distribution":"Daily accrued dividends are distributed monthly as new tokens","target_nav_usd":1,"target_nav_not_guaranteed":true,"holder_right":"A BUIDL token represents a restricted fund interest, not equity in BlackRock or Securitize."},
  "data_scope_notes":["Product total asset value is kept separate from Securitize platform AUM and assets under administration.","RWA.xyz labels ten current token rows native while seven rows use Wormhole NTT as a base protocol; contract-level provenance remains a review item rather than a claim that all representations are permissionless bridge tokens.","Seven-day APY is a dated trailing observation, not a promised return."],
  "canonical_profile":{
    "schema":"chaindump-entity-profile-source",
    "version":1,
    "classification":{"subtype":"rwa-treasuries","tags":["tokenized-fund","private-placement","qualified-purchaser","cash-management"],"chains":["Aptos","Arbitrum","Avalanche C-Chain","BNB Chain","Ethereum","Optimism","Polygon","Solana","Tempo"],"jurisdictions":["British Virgin Islands","United States"]},
    "status":{"operating_state":"operating","as_of":"2026-08-03","claim_ids":["claim:buidl:operating-state"]},
    "outcome":{"label":null,"as_of":null,"rule_id":null,"confidence":null,"claim_ids":[]},
    "sections":{
      "what_it_is":"BUIDL is a private pooled investment fund issued by a British Virgin Islands company and managed by BlackRock Financial Management. Its shares are represented as digital asset security tokens. The reviewed Form D claims Rule 506(c) and the Investment Company Act section 3(c)(7) exclusion; tokenization does not make the fund interest permissionless or exchange-listed.",
      "what_happened":"The fund launched on Ethereum in March 2024, added issuer-sponsored share classes across more public networks, and later entered controlled collateral and secondary-liquidity workflows. RWA.xyz recorded ten native token rows on nine named networks on 2026-08-03. Its product-level total asset value is stored as a dated metric, not repeated as an evergreen superlative.",
      "why_this_outcome":"BUIDL combines a familiar short-duration reserve portfolio with blockchain settlement, a regulated transfer-agent workflow and a large service-provider network. That combination plausibly reduced operational friction for already-qualified institutions. It does not show that public-chain deployment removed legal eligibility, wallet approval or transfer controls.",
      "strategic_choices":"The product targets a one-dollar share value, distributes accrued income as additional tokens, gates investors and wallets through Securitize, and expands through separate network share classes and selected collateral venues. Those choices favor controlled institutional distribution and composability over unrestricted bearer-style transfer.",
      "operating_model":"The fund invests all assets in cash, United States Treasury bills and repurchase agreements. BlackRock Financial Management manages investments; BNY Mellon provides custody and administration; Securitize provides the platform, transfer-agent, registrar and paying-agent functions; Securitize Markets acts as placement agent. Onboarding includes identity, sanctions and wallet checks, and peer transfers are limited to approved participants.",
      "token_and_value_capture":"BUIDL seeks a stable one-dollar token value while daily accrued dividends are paid monthly as new tokens. The current fee range varies by share class. Holders receive economics of the fund interest after expenses; the token does not establish a claim on BlackRock or Securitize equity, and a trailing APY observation is not a guaranteed return.",
      "counterfactual":"Without whitelisted transfer-agent controls, BUIDL could move more freely but would not preserve the documented private-placement workflow. Without multiple network share classes and collateral integrations, operations would be simpler but distribution and utility would be narrower. These are analytical trade-offs, not measured causal effects.",
      "risks_and_unknowns":"The launch disclosures warn that BUIDL may not maintain one dollar and that investors can lose principal. Material risks include private-placement illiquidity, eligibility and transfer restrictions, interest-rate and portfolio risk, issuer and service-provider dependence, smart-contract and wallet risk, and cross-network reconciliation. Public network visibility does not remove those constraints.",
      "lifecycle":"BUIDL launched on Ethereum on 2024-03-20. New share classes brought it to seven networks by 2025-03-25 and BNB Chain on 2025-11-14. A 2026 UniswapX workflow added bilateral onchain quote and settlement technology while retaining pre-qualification and whitelisting. The fund remained operating on 2026-08-03.",
      "outlook_and_watch":"Watch product-level asset value, share-class fees and dividends; changes to offering and eligibility terms; custody and transfer-agent arrangements; collateral integrations; and reconciliation of every network contract and Wormhole-enabled share class. Platform-wide Securitize figures must remain separate from BUIDL fund value, and current yield must remain a dated observation."
    },
    "section_dates":{"what_it_is":"2026-08-03","what_happened":"2026-08-03","why_this_outcome":"2026-08-03","strategic_choices":"2026-08-03","operating_model":"2026-08-03","token_and_value_capture":"2026-08-03","counterfactual":"2026-08-03","risks_and_unknowns":"2026-08-03","lifecycle":"2026-08-03","outlook_and_watch":"2026-08-03"},
