      {"id":"claim:buidl:current-market","field_path":"analysis.sections.what_happened.body","statement":"RWA.xyz recorded material BUIDL product value, a one-dollar NAV and current holder and yield observations on 2026-08-03.","source_ids":["rwa-buidl"],"evidence_locator":"Server-rendered asset aggregates and update timestamp","support_direction":"supports","note":"Product observations are not Securitize platform AUM and yield is not promised.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},
      {"id":"claim:buidl:why","field_path":"analysis.sections.why_this_outcome.body","statement":"BUIDL adoption is plausibly supported by short-duration assets, controlled onchain settlement and institutional service providers.","source_ids":["securitize-buidl-launch","sec-buidl-transfer-agent","rwa-buidl"],"evidence_locator":"Product design, operating agreement and current product observation","support_direction":"context_only","note":"Analytical inference; the sources do not isolate causal contribution.","review":{"state":"pending","reviewer":null,"reviewed_at":null}},
