UPDATE rwa_depin
SET
  name = CASE lower(slug)
    WHEN 'blackrock-buidl' THEN 'BlackRock BUIDL'
    WHEN 'ondo-finance' THEN 'Ondo Finance / OUSG'
    ELSE name
  END,
  category = 'rwa-treasuries',
  status = 'operating',
  profile = json_set(
    json((SELECT profile FROM _rwa_control_profiles WHERE lower(_rwa_control_profiles.slug) = lower(rwa_depin.slug))),
    '$.sources',
    json((SELECT sources FROM _rwa_control_profiles WHERE lower(_rwa_control_profiles.slug) = lower(rwa_depin.slug)))
  ),
  sources = (SELECT sources FROM _rwa_control_profiles WHERE lower(_rwa_control_profiles.slug) = lower(rwa_depin.slug)),
  updated_at = '2026-08-03'
WHERE lower(slug) IN ('blackrock-buidl', 'ondo-finance');

